import json

def dedup_report(rows, key_fn):
    seen, unique, conflicts = {}, [], []
    for row in rows:
        key = key_fn(row)
        if key not in seen:
            seen[key] = row
            unique.append(row)
        elif seen[key] != row:
            conflicts.append({'key': key, 'kept': seen[key], 'other': row})
    return {'unique': unique, 'conflicts': conflicts}

def flatten_txs(clients):
    return [{'client_id': c['id'], 'tx_id': t['id'], 'monto': t['monto']} for c in clients for t in c['txs']]

def get_nested(d, *keys, default=None):
    cur = d
    for key in keys:
        if not isinstance(cur, dict) or key not in cur:
            return default
        cur = cur[key]
    return cur

def export_deterministic(clients):
    return json.dumps(sorted(clients, key=lambda c: c['id']), sort_keys=True, ensure_ascii=False)

