    return [{'id':'C001','nombre':'Ana Quispe','contacts':[{'tipo':'email','valor':'ana@example.com'}],'txs':[{'id':'T1','monto':10},{'id':'T2','monto':5}]},{'id':'C002','nombre':'Luis Huamán','contacts':[],'txs':[{'id':'T3','monto':20}]}]

